import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M, S, T = map(int, input().split())
    S -= 1
    T -= 1

    g = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        g[u].append(v)
        g[v].append(u)

    INF = 10**18

    def bfs(start):
        dist = [INF] * N
        dist[start] = 0
        q = deque([start])
        while q:
            v = q.popleft()
            for to in g[v]:
                if dist[to] == INF:
                    dist[to] = dist[v] + 1
                    q.append(to)
        return dist

    ds = bfs(S)
    dt = bfs(T)
    d = ds[T]

    color = [-1] * N
    color[0] = 0
    q = deque([0])
    bipartite = True
    while q:
        v = q.popleft()
        for to in g[v]:
            if color[to] == -1:
                color[to] = color[v] ^ 1
                q.append(to)
            elif color[to] == color[v]:
                bipartite = False

    if bipartite and color[S] != color[T]:
        print(-1)
        return

    ans = INF

    if color[S] == color[T]:
        # Both pieces can move along two internally vertex-disjoint shortest
        # paths around an even cycle. Equivalently, find an edge connecting two
        # consecutive distance layers from S and T.
        for v in range(N):
            for to in g[v]:
                val = ds[v] + 1 + dt[to]
                if val == d:
                    continue
                if ds[to] + 1 + dt[v] == d:
                    continue
                ans = min(ans, ds[v] + dt[v] + ds[to] + dt[to] + 2)

    if not bipartite:
        # One token follows a shortest S-T path. The other follows the shortest
        # S-T walk with the opposite parity, which exists exactly in a
        # non-bipartite connected graph.
        dist = [[INF, INF] for _ in range(N)]
        dist[S][0] = 0
        q = deque([(S, 0)])
        while q:
            v, p = q.popleft()
            for to in g[v]:
                np = p ^ 1
                if dist[to][np] == INF:
                    dist[to][np] = dist[v][p] + 1
                    q.append((to, np))
        ans = min(ans, d + dist[T][(d & 1) ^ 1])

    print(-1 if ans == INF else ans)

if __name__ == "__main__":
    main()
